package com.alpharip.staffmod.IncidentPostMortemBoard; public final class IncidentPostMortemFilter { private IncidentStatus status;private IncidentSeverity severity;private IncidentCategory category;private String text; public IncidentPostMortemFilter(IncidentStatus s,IncidentSeverity v,IncidentCategory c,String q){status=s;severity=v;category=c;text=q==null?"":q.trim().toLowerCase();} public boolean matches(IncidentRecord r){if(r==null)return false;if(status!=null&&r.getStatus()!=status)return false;if(severity!=null&&r.getSeverity()!=severity)return false;if(category!=null&&r.getCategory()!=category)return false;return text.isEmpty()||r.getTitle().toLowerCase().contains(text)||r.getDescription().toLowerCase().contains(text)||r.getReporter().toLowerCase().contains(text)||r.getOwner().toLowerCase().contains(text);} }